import sys

def find_nth_element(n):
    if n <= 3:
        return n
    k = (n - 3) // 3
    r = (n - 3) % 3
    base = 4 * (k + 1)
    if r == 0:
        return base - 3
    elif r == 1:
        return base - 1
    else:
        return base - 2

t = int(sys.stdin.readline())
results = []
for _ in range(t):
    n = int(sys.stdin.readline())
    results.append(find_nth_element(n))
print(" ".join(map(str, results)))
